</div>
<div id="ctrls">ARROWS / WASD move &bull; SPACE shoot &bull; idle 3s = autopilot</div>
<script src="https://unpkg.com/three@0.160.0/build/three.min.js"></script>
<script>
const PI2=Math.PI*2;
let audioCtx;
function audio(){if(!audioCtx){const Ctx=window.AudioContext||window.webkitAudioContext;audioCtx=new Ctx();}return audioCtx;}
function tone(freq,type,duration,vol,time){
  const ctx=audio();const t=time||ctx.currentTime;const o=ctx.createOscillator();const g=ctx.createGain();
  o.type=type;o.frequency.setValueAtTime(freq,t);g.gain.setValueAtTime(vol||0.1,t);g.gain.exponentialRampToValueAtTime(0.001,t+duration);
  o.connect(g);g.connect(ctx.destination);o.start(t);o.stop(t+duration);
}
function noiseBurst(duration,vol,time){
  const ctx=audio();const t=time||ctx.currentTime;const bufSize=ctx.sampleRate*duration;const buf=ctx.createBuffer(1,bufSize,ctx.sampleRate);const d=buf.getChannelData(0);
  for(let i=0;i<bufSize;i++)d[i]=(Math.random()*2-1);
  const n=ctx.createBufferSource();n.buffer=buf;const g=ctx.createGain();g.gain.setValueAtTime(vol||0.15,t);g.gain.exponentialRampToValueAtTime(0.001,t+duration);
  n.connect(g);g.connect(ctx.destination);n.start(t);n.stop(t+duration);
}
function sShoot(){const ctx=audio();const t=ctx.currentTime;tone(880,'square',0.06,0.12,t);tone(1320,'square',0.06,0.08,t+0.03);}
function sHit(){tone(220,'sawtooth',0.12,0.15);}
function sExplode(){noiseBurst(0.4,0.2);tone(60,'sawtooth',0.5,0.1);tone(100,'sawtooth',0.3,0.05,0.1);}
function sGameOver(){const ctx=audio();const t=ctx.currentTime;[220,180,140,110].forEach((f,i)=>tone(f,'sawtooth',0.4,0.12,t+i*0.15));}
function sSpawn(){tone(400,'sine',0.1,0.05);}

let scene,camera,renderer,clock,player,bullets=[],asteroids=[],particles=[],stars;
let score=0,lives=3,state='ATTRACT';
let lastInput=0,invincible=0,respawn=0,shake=0;
const keys={};
const msg=document.getElementById('msg');const sub=document.getElementById('sub');const elScore=document.getElementById('score');const elLives=document.getElementById('lives');

function init(){
  scene=new THREE.Scene();scene.fog=new THREE.FogExp2(0x040408,0.0015);
  camera=new THREE.PerspectiveCamera(55,innerWidth/innerHeight,0.1,1000);camera.position.set(0,8,22);camera.lookAt(0,0,0);
  renderer=new THREE.WebGLRenderer({antialias:true});renderer.setSize(innerWidth,innerHeight);renderer.setPixelRatio(Math.min(devicePixelRatio,2));document.body.appendChild(renderer.domElement);
  clock=new THREE.Clock();
  stars=new THREE.Group();
  const geo=new THREE.SphereGeometry(0.04,6,6);const mat=new THREE.MeshBasicMaterial({color:#ffffff});
  for(let i=0;i<300;i++){const m=new THREE.Mesh(geo,mat);m.position.set(Math.random()*400-200,Math.random()*400-200,Math.random()*400-200);stars.add(m);}
  scene.add(stars);
  createPlayer();
  resetGame();
  window.addEventListener('keydown',e=>{lastInput=performance.now();if(e.code==='Space'){e.preventDefault();handleSpace();}keys[e.code]=true;if(state==='ATTRACT'||state==='GAMEOVER')startGame();});
  window.addEventListener('keyup',e=>{keys[e.code]=false;});
  window.addEventListener('resize',onResize);
  audio();
  animate();
}
function createPlayer(){
  if(player){scene.remove(player);player.traverse(c=>{if(c.geometry)c.geometry.dispose();if(c.material)c.material.dispose();});}
  player=new THREE.Group();
  const body=new THREE.Mesh(new THREE.ConeGeometry(0.5,1.2,8),new THREE.MeshBasicMaterial({color:#0ff}));
  body.rotation.x=-Math.PI/2;player.add(body);
  const wingL=new THREE.Mesh(new THREE.BoxGeometry(1.2,0.15,0.4),new THREE.MeshBasicMaterial({color:#0ff}));wingL.position.set(-0.65,0,0.3);player.add(wingL);
  const wingR=new THREE.Mesh(new THREE.BoxGeometry(1.2,0.15,0.4),new THREE.MeshBasicMaterial({color:#0ff}));wingR.position.set(0.65,0,0.3);player.add(wingR);
  const cockpit=new THREE.Mesh(new THREE.SphereGeometry(0.18,8,8),new THREE.MeshBasicMaterial({color:#fff}));cockpit.position.set(0,0.1,0.2);player.add(cockpit);
  player.position.set(0,-2,0);player.rotation.x=-0.4;
  scene.add(player);
}
function resetGame(){score=0;lives=3;bullets.forEach(b=>scene.remove(b));bullets=[];asteroids.forEach(a=>scene.remove(a));asteroids=[];particles.forEach(p=>scene.remove(p));particles=[];updateHud();sub.textContent='Press SPACE to start';msg.classList.remove('hidden');}
function startGame(){if(state==='PLAYING')return;state='PLAYING';score=0;lives=3;bullets.forEach(b=>scene.remove(b));bullets=[];asteroids.forEach(a=>scene.remove(a));asteroids=[];particles.forEach(p=>scene.remove(p));particles=[];createPlayer();updateHud();spawnAsteroid(4);msg.classList.add('hidden');invincible=1.5;sSpawn();}
function handleSpace(){if(state!=='PLAYING')return;shoot();}
function shoot(){if(state!=='PLAYING')return;sShoot();const b=new THREE.Mesh(new THREE.SphereGeometry(0.08,6,6),new THREE.MeshBasicMaterial({color:#0ff}));
  const dir=new THREE.Vector3();player.getWorldDirection(dir);b.position.copy(player.position).addScaledVector(dir,0.8);b.userData={dir:dir.clone(),life:1.2};scene.add(b);bullets.push(b);}
function spawnAsteroid(count,overrideSize){
  for(let i=0;i<count;i++){
    const size=overrideSize||['large','medium','small'][Math.floor(Math.random()*3)];
    const m=new THREE.Mesh(new THREE.IcosahedronGeometry(size==='large'?1.4:size==='medium'?0.85:0.5,2),new THREE.MeshBasicMaterial({color:#aaa,wireframe:true}));
    let x,y,z;do{x=(Math.random()*2-1)*25;y=(Math.random()*2-1)*18;z=(Math.random()*2-1)*30;}while(Math.sqrt(x*x+y*y+z*z)<14);
    m.position.set(x,y,z);m.userData={size,vel:new THREE.Vector3((Math.random()*2-1)*0.04,(Math.random()*2-1)*0.04,(Math.random()*2-1)*0.04),rot:new THREE.Vector3(Math.random()*0.01,Math.random()*0.01,Math.random()*0.01),hp:size==='large'?2:1};
    scene.add(m);asteroids.push(m);
  }
}
function explode(pos,scale){
  sExplode();const c=scale||1;
  for(let i=0;i<12*c;i++){
    const p=new THREE.Mesh(new THREE.SphereGeometry(0.06,5,5),new THREE.MeshBasicMaterial({color:#0ff}));
    p.position.copy(pos);p.userData={vel:new THREE.Vector3((Math.random()*2-1)*0.15,(Math.random()*2-1)*0.15,(Math.random()*2-1)*0.15),life:0.6};scene.add(p);particles.push(p);
  }
}
function splitAsteroid(idx){
  const a=asteroids[idx];const pos=a.position.clone();const size=a.userData.size;let next;
  if(size==='large')next='medium';else if(size==='medium')next='small';else{scene.remove(a);asteroids.splice(idx,1);return;}
  const n1=new THREE.Mesh(new THREE.IcosahedronGeometry(next==='medium'?0.85:0.5,2),new THREE.MeshBasicMaterial({color:#aaa,wireframe:true}));
  const n2=n1.clone();[n1,n2].forEach(m=>{m.position.copy(pos);m.userData={size:next,vel:new THREE.Vector3((Math.random()*2-1)*0.05,(Math.random()*2-1)*0.05,(Math.random()*2-1)*0.05),rot:new THREE.Vector3(Math.random()*0.01,Math.random()*0.01,Math.random()*0.01),hp:1};scene.add(m);asteroids.push(m);});
  scene.remove(a);asteroids.splice(idx,1);explode(pos,1.5);
}
function hitPlayer(){
  if(invincible>0||state!=='PLAYING')return;lives--;sHit();explode(player.position.clone(),2);updateHud();invincible=2;if(lives<=0){state='GAMEOVER';sGameOver();sub.textContent='GAME OVER  Press SPACE';msg.classList.remove('hidden');return;}
  respawn=1.2;player.visible=false;setTimeout(()=>{createPlayer();player.visible=true;invincible=1.5;},1100);
}
function updateHud(){elScore.textContent=score;elLives.textContent=lives;}
function onResize(){camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight);}
function autopilot(dt){
  if(state!=='PLAYING'&&state!=='ATTRACT')return;
  let target=null,d=1e9;asteroids.forEach(a=>{const dd=a.position.distanceTo(player.position);if(dd<d){d=dd;target=a;}});
  if(!target)return;
  const dir=new THREE.Vector3().subVectors(target.position,player.position).normalize();const angle=Math.atan2(dir.x,dir.z);const cur=player.rotation.y;let diff=angle-cur;while(diff>Math.PI)diff-=PI2;while(diff<-Math.PI)diff+=PI2;
  player.rotation.y+=diff*0.06*60*dt;player.rotation.x=-0.4+diff*0.15;
  const fwd=new THREE.Vector3();player.getWorldDirection(fwd);player.position.addScaledVector(fwd,0.12*60*dt);
