  if(state!=='PLAYING'){if(state==='ATTRACT'){particles.forEach(p=>{p.position.add(p.userData.vel);p.userData.life-=dt;p.scale.setScalar(p.userData.life/0.6);});particles=particles.filter(p=>p.userData.life>0);asteroids.forEach(a=>{a.position.add(a.userData.vel);a.rotation.x+=a.userData.rot.x;a.rotation.y+=a.userData.rot.y;a.rotation.z+=a.userData.rot.z;});}renderer.render(scene,camera);requestAnimationFrame(update);return;}
  if(keys['ArrowLeft']||keys['KeyA'])player.rotation.y-=0.09;
  if(keys['ArrowRight']||keys['KeyD'])player.rotation.y+=0.09;
  if(keys['ArrowUp']||keys['KeyW']){const f=new THREE.Vector3();player.getWorldDirection(f);f.y=0;f.normalize();player.position.addScaledVector(f,0.15);}
