  if(invincible>0){invincible-=dt;player.traverse(c=>{if(c.material)c.material.opacity=0.4+Math.sin(now*0.02)*0.3;});}
  for(let i=bullets.length-1;i>=0;i--){const b=bullets[i];b.position.addScaledVector(b.userData.dir,0.35);b.userData.life-=dt;if(b.userData.life<=0||Math.abs(b.position.x)>40||Math.abs(b.position.z)>40){scene.remove(b);bullets.splice(i,1);continue;}
    for(let j=asteroids.length-1;j>=0;j--){if(b.position.distanceTo(asteroids[j].position)<1){scene.remove(b);bullets.splice(i,1);asteroids[j].userData.hp--;if(asteroids[j].userData.hp<=0){score+=asteroids[j].userData.size==='large'?20:asteroids[j].userData.size==='medium'?50:100;sHit();splitAsteroid(j);updateHud();}else sHit();break;}}
  }
  for(let i=asteroids.length-1;i>=0;i--){const a=asteroids[i];a.position.add(a.userData.vel);a.rotation.x+=a.userData.rot.x;a.rotation.y+=a.userData.rot.y;a.rotation.z+=a.userData.rot.z;if(Math.abs(a.position.x)>45)a.position.x=-(Math.sign(a.position.x)*45);if(Math.abs(a.position.z)>55)a.position.z=-(Math.sign(a.position.z)*55);if(a.position.distanceTo(player.position)<1.3&&invincible<=0)hitPlayer();}
  particles.forEach(p=>{p.position.add(p.userData.vel);p.userData.life-=dt;p.scale.setScalar(Math.max(0,p.userData.life/0.6));});particles=particles.filter(p=>p.userData.life>0);
  if(respawn>0){respawn-=dt;if(respawn<=0){createPlayer();invincible=1.5;}}
  if(shake>0){shake-=dt;camera.position.x=(Math.random()*2-1)*shake;camera.position.y=8+(Math.random()*2-1)*shake;}
  else{camera.position.x=0;camera.position.y=8;}
  camera.lookAt(player.position);
  renderer.render(scene,camera);
  requestAnimationFrame(update);
}
init();
</script>
